select jsonb_build_object('table',(select jsonb_build_object('rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,'acl',c.relacl) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname='conversation_user_state'),'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'default',pg_get_expr(ad.adbin,ad.adrelid)) order by a.attnum) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef ad on ad.adrelid=a.attrelid and ad.adnum=a.attnum where n.nspname='public' and c.relname='conversation_user_state' and a.attnum>0 and not a.attisdropped),'constraints',(select jsonb_agg(jsonb_build_object('name',con.conname,'type',con.contype::text,'definition',pg_get_constraintdef(con.oid,true),'validated',con.convalidated) order by con.conname) from pg_constraint con join pg_class c on c.oid=con.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname='conversation_user_state'),'indexes',(select jsonb_agg(jsonb_build_object('name',indexname,'definition',indexdef) order by indexname) from pg_indexes where schemaname='public' and tablename='conversation_user_state'),'policy',(select jsonb_agg(jsonb_build_object('name',policyname,'roles',roles,'command',cmd,'using',qual,'withCheck',with_check) order by policyname) from pg_policies where schemaname='public' and tablename='conversation_user_state'),'triggers',(select jsonb_agg(jsonb_build_object('table',c.relname,'name',t.tgname,'definition',pg_get_triggerdef(t.oid,true),'enabled',t.tgenabled::text,'function',p.proname) order by c.relname,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace join pg_proc p on p.oid=t.tgfoid where n.nspname='public' and t.tgname in ('conversation_user_state_touch_updated_at','chat_participants_sync_conversation_user_state','aa_chat_messages_after_insert_reactivate_user_state') and not t.tgisinternal),'functions',(select jsonb_agg(jsonb_build_object('name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'md5',md5(replace(pg_get_functiondef(p.oid),E'\\r\\n',E'\\n')),'securityDefiner',p.prosecdef,'volatility',p.provolatile::text,'config',coalesce(p.proconfig,array[]::text[]),'acl',p.proacl) order by p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('quata_chat_touch_conversation_user_state_updated_at','quata_chat_first_message_id','quata_chat_ensure_conversation_user_state','quata_chat_participant_sync_user_state','quata_chat_reactivate_user_state_for_message','quata_chat_thread_json','quata_chat_get_thread','quata_chat_get_inbox','quata_chat_send_message','quata_chat_mark_thread_read','quata_chat_mark_messages_state','quata_chat_set_muted','quata_chat_delete_thread','quata_chat_restore_thread','quata_chat_list_shared_attachments')),'missingParticipantStates',(select count(*)::int from public.chat_participants p left join public.conversation_user_state s on s.conversation_id=p.thread_id and s.user_id=p.profile_id where s.user_id is null),'missingVisibilityBoundaries',(select count(*)::int from public.conversation_user_state s where s.first_visible_message_id is null and exists(select 1 from public.chat_messages m where m.thread_id=s.conversation_id))) observation;
